BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "deklaracje" (
	"id"	INTEGER,
	"typ"	VARCHAR(30) NOT NULL,
	"okres"	VARCHAR(20) NOT NULL,
	"status"	VARCHAR(30) NOT NULL,
	"podstawa"	DECIMAL(12, 2),
	"vat_naliczony"	DECIMAL(12, 2),
	"vat_nalezny"	DECIMAL(12, 2),
	"data_zlozenia"	DATE,
	"klient_id"	INTEGER NOT NULL,
	"uzytkownik_id"	INTEGER,
	"utworzono"	timestamp,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("klient_id") REFERENCES "klienci"("id"),
	FOREIGN KEY("uzytkownik_id") REFERENCES "uzytkownicy"("id")
);
CREATE TABLE IF NOT EXISTS "faktury" (
	"id"	INTEGER,
	"numer"	VARCHAR(50) NOT NULL UNIQUE,
	"typ"	VARCHAR(30) NOT NULL,
	"data_wystawienia"	DATE NOT NULL,
	"data_platnosci"	DATE,
	"kwota_netto"	DECIMAL(12, 2),
	"kwota_vat"	DECIMAL(12, 2),
	"kwota_brutto"	DECIMAL(12, 2),
	"status"	VARCHAR(30) NOT NULL,
	"waluta"	VARCHAR(3),
	"klient_id"	INTEGER NOT NULL,
	"kontrahent_id"	INTEGER,
	"uzytkownik_id"	INTEGER,
	"utworzono"	timestamp,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("klient_id") REFERENCES "klienci"("id"),
	FOREIGN KEY("kontrahent_id") REFERENCES "kontrahenci"("id"),
	FOREIGN KEY("uzytkownik_id") REFERENCES "uzytkownicy"("id")
);
CREATE TABLE IF NOT EXISTS "klienci" (
	"id"	INTEGER,
	"nazwa"	VARCHAR(200) NOT NULL,
	"nip"	VARCHAR(10) UNIQUE,
	"adres"	VARCHAR(200),
	"email"	VARCHAR(255),
	"telefon"	VARCHAR(20),
	"utworzono"	TIMESTAMP,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "kontrahenci" (
	"id"	INTEGER,
	"nazwa"	VARCHAR(200) NOT NULL,
	"nip"	VARCHAR(10) UNIQUE,
	"adres"	VARCHAR(200),
	"email"	VARCHAR(255),
	"telefon"	VARCHAR(20),
	"utworzono"	TIMESTAMP,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "ksiegi_rachunkowe" (
	"id"	integer,
	"data_ksiegowania"	date NOT NULL,
	"konto_ma"	varchar(255) NOT NULL,
	"konto_winien"	varchar(255) NOT NULL,
	"kwota"	numeric(12, 2) NOT NULL,
	"opis"	varchar(500),
	"faktura_id"	bigint,
	"uzytkownik_id"	bigint,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "pozycje_faktury" (
	"id"	INTEGER,
	"nazwa"	VARCHAR(255) NOT NULL,
	"ilosc"	DECIMAL(12, 2),
	"jednostka"	VARCHAR(20),
	"cena_netto"	DECIMAL(12, 2),
	"stawka_vat"	DECIMAL(5, 2),
	"faktura_id"	INTEGER NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("faktura_id") REFERENCES "faktury"("id") ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "raporty" (
	"id"	integer,
	"data_wygenerowania"	timestamp,
	"podstawa"	numeric(12, 2),
	"typ_rejestru"	varchar(255) CHECK(("typ_rejestru" IN ('ZAKUP', 'SPRZEDAZ'))),
	"vat_nalezny"	numeric(12, 2),
	"vat_naliczony"	numeric(12, 2),
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "rejestr_vat" (
	"id"	integer,
	"okres"	varchar(255) NOT NULL,
	"podstawa"	numeric(12, 2),
	"typ_rejestru"	varchar(255) NOT NULL CHECK(("typ_rejestru" IN ('ZAKUP', 'SPRZEDAZ'))),
	"vat_nalezny"	numeric(12, 2),
	"vat_naliczony"	numeric(12, 2),
	"faktura_id"	bigint,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "uzytkownicy" (
	"id"	INTEGER,
	"imie"	VARCHAR(50) NOT NULL,
	"nazwisko"	VARCHAR(50) NOT NULL,
	"email"	VARCHAR(255) NOT NULL UNIQUE,
	"haslo"	VARCHAR(255) NOT NULL,
	"rola"	VARCHAR(50) NOT NULL,
	"aktywny"	INTEGER NOT NULL DEFAULT 0,
	"utworzono"	TIMESTAMP,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE INDEX IF NOT EXISTS "idx_faktury_data" ON "faktury" (
	"data_wystawienia"
);
CREATE INDEX IF NOT EXISTS "idx_faktury_klient" ON "faktury" (
	"klient_id"
);
CREATE INDEX IF NOT EXISTS "idx_pozycje_faktura" ON "pozycje_faktury" (
	"faktura_id"
);
COMMIT;
